changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Espagne – Dirigeants des partis et syndicats (Wikidata)', 'Dirigeants des partis représentés au Parlement, des principaux syndicats et des organisations patronales, d''après Wikidata (blocs ES-h et ES-SIND)', 'es_pep_parties_unions', 'PEP', 'https://www.wikidata.org', 'es-pep-parties-unions', 'D:/test parser 2/plugins/swiftcheck-aml-es-pep-parties-unions-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'SPARQL', NULL, '{"endpoint":"https://query.wikidata.org/sparql","monthsAfterEnd":"24","delayMs":"2000","kind":"heads","entities":"Q138198 Q185088 Q15630787 Q112098527 Q150068 Q97155800 Q1029761 Q43093 Q885433 Q1104327 Q16059622 Q2001535 Q833196 Q393165 Q5782715","properties":"P488 P3320 P3975","positionLabel":"Dirigeant de {subject}","topics":"gov.national","openSince":"2015-01-01"}', 168, 24, 'CC0 (Wikidata)', 'Wikidata, www.wikidata.org', 'Quinze organisations configurées (PSOE, PP, Vox, Sumar, ERC, Junts, EH Bildu, PNV, BNG, CC, Podemos, CCOO, UGT, CEOE, Cepyme) ; Wikidata donne le président ou secrétaire général et parfois un second dirigeant. Pas de page de direction lisible de façon uniforme. Données collaboratives de Wikidata : un changement de titulaire non saisi n''est pas vu, à contrôler.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les présidents et secrétaires généraux des partis représentés au Parlement décrits dans Wikidata.', 'Seulement un à deux dirigeants par parti (Wikidata) : pas les comités exécutifs.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-h' AND f.label LIKE 'Membre de la direction d''un parti représenté%' AND p.dataset_name = 'es_pep_parties_unions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les dirigeants de CCOO et de l’UGT décrits dans Wikidata.', 'CEOE et Cepyme sans dirigeant daté dans Wikidata ; pas les comités exécutifs.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-SIND' AND f.label LIKE 'Membre de la haute direction d''un syndicat%' AND p.dataset_name = 'es_pep_parties_unions';
